 'F3_Z01_temp':'e0dd5f44-f050-5faa-a2a0-a3fcb6284ae8',
 'F3_Z02_temp':'bcc5a78f-36a4-55a0-9420-7a80fc9b2deb',
 'F3_Z05_temp':'c49bbc2f-096e-5e16-bead-066250790308',
 'F3_Z01_damp':'de92aecc-fc37-5d28-a0b6-fb34b4c34747',
 'F3_Z02_damp':'7b02c527-bd84-5ef0-825f-0c8f9da917ba',
 'F4_Z01_temp':'14a08406-79a0-52ca-b8a1-8563259dc820',
 'F2_Z01_temp':'baef86cb-2941-5d61-87b0-ffa91d79f23a',
}
data={k:defaultdict(float) for k in series}
