        for k,v in series.items():
            if v==r['timeseries_id']:
                data[k][r['timestamp']]=float(r['value'])

def half_stats(k,split='2018-07-01'):
    a=[v for t,v in data[k].items() if t<split]
    b=[v for t,v in data[k].items() if t>=split]
    return (round(statistics.mean(a),2), round(statistics.mean(b),2))
print('means before vs after 2018-07-01:')
